/* 自动生成，用于本地预览。重新生成： node tools/fetch-data.cjs */
window.__TEDL_SAMPLE__ = {
  talkId: "66",
  title: "Do schools kill creativity?",
  en: [{"duration":2575,"content":"Good morning. How are you?","startOfParagraph":true,"startTime":2103},{"duration":1403,"content":"(Audience) Good.","startOfParagraph":true,"startTime":4702},{"duration":1668,"content":"It's been great, hasn't it?","startOfParagraph":true,"startTime":6129},{"duration":2321,"content":"I've been blown away by the whole thing.","startOfParagraph":false,"startTime":8408},{"duration":1492,"content":"In fact, I'm leaving.","startOfParagraph":false,"startTime":10753},{"duration":3906,"content":"(Laughter)","startOfParagraph":true,"startTime":12269},{"duration":3567,"content":"There have been three themes\nrunning through the conference,","startOfParagraph":true,"startTime":18096},{"duration":2286,"content":"which are relevant\nto what I want to talk about.","startOfParagraph":false,"startTime":21687},{"duration":4470,"content":"One is the extraordinary\nevidence of human creativity","startOfParagraph":false,"startTime":23997},{"duration":2413,"content":"in all of the presentations that we've had","startOfParagraph":false,"startTime":28491},{"duration":1952,"content":"and in all of the people here;","startOfParagraph":false,"startTime":30928},{"duration":2651,"content":"just the variety of it\nand the range of it.","startOfParagraph":false,"startTime":32904},{"duration":2143,"content":"The second is that it's put us in a place","startOfParagraph":false,"startTime":36158},{"duration":2497,"content":"where we have no idea\nwhat's going to happen","startOfParagraph":false,"startTime":38325},{"duration":1391,"content":"in terms of the future.","startOfParagraph":false,"startTime":40846},{"duration":2985,"content":"No idea how this may play out.","startOfParagraph":false,"startTime":42261},{"duration":1622,"content":"I have an interest in education.","startOfParagraph":true,"startTime":45270},{"duration":4412,"content":"Actually, what I find is,\neverybody has an interest in education.","startOfParagraph":false,"startTime":46916},{"duration":1317,"content":"Don't you?","startOfParagraph":false,"startTime":51352},{"duration":1402,"content":"I find this very interesting.","startOfParagraph":false,"startTime":52693},{"duration":3958,"content":"If you're at a dinner party,\nand you say you work in education --","startOfParagraph":false,"startTime":54119},{"duration":2745,"content":"actually, you're not often\nat dinner parties, frankly.","startOfParagraph":false,"startTime":58101},{"duration":3796,"content":"(Laughter)","startOfParagraph":true,"startTime":60870},{"duration":2428,"content":"If you work in education,\nyou're not asked.","startOfParagraph":true,"startTime":64690},{"duration":3179,"content":"(Laughter)","startOfParagraph":true,"startTime":67142},{"duration":3959,"content":"And you're never asked back, curiously.\nThat's strange to me.","startOfParagraph":true,"startTime":70345},{"duration":2216,"content":"But if you are, and you say to somebody,","startOfParagraph":false,"startTime":74328},{"duration":1778,"content":"you know, they say, \"What do you do?\"","startOfParagraph":false,"startTime":76568},{"duration":1688,"content":"and you say you work in education,","startOfParagraph":false,"startTime":78370},{"duration":2049,"content":"you can see the blood run from their face.","startOfParagraph":false,"startTime":80082},{"duration":1685,"content":"They're like, \"Oh my God. Why me?\"","startOfParagraph":false,"startTime":82155},{"duration":2276,"content":"(Laughter)","startOfParagraph":true,"startTime":83864},{"duration":1524,"content":"\"My one night out all week.\"","startOfParagraph":true,"startTime":86164},{"duration":2610,"content":"(Laughter)","startOfParagraph":true,"startTime":87712},{"duration":3241,"content":"But if you ask about their education,\nthey pin you to the wall,","startOfParagraph":true,"startTime":90346},{"duration":3407,"content":"because it's one of those things\nthat goes deep with people, am I right?","startOfParagraph":false,"startTime":93611},{"duration":3493,"content":"Like religion and money and other things.","startOfParagraph":false,"startTime":97042},{"duration":4442,"content":"So I have a big interest in education,\nand I think we all do.","startOfParagraph":false,"startTime":100559},{"duration":1802,"content":"We have a huge vested interest in it,","startOfParagraph":false,"startTime":105025},{"duration":3320,"content":"partly because it's education\nthat's meant to take us into this future","startOfParagraph":false,"startTime":106851},{"duration":1654,"content":"that we can't grasp.","startOfParagraph":false,"startTime":110195},{"duration":1166,"content":"If you think of it,","startOfParagraph":false,"startTime":111873},{"duration":6122,"content":"children starting school this year\nwill be retiring in 2065.","startOfParagraph":false,"startTime":113063},{"duration":1571,"content":"Nobody has a clue,","startOfParagraph":false,"startTime":120272},{"duration":3559,"content":"despite all the expertise that's been\non parade for the past four days,","startOfParagraph":false,"startTime":121867},{"duration":2526,"content":"what the world will look like\nin five years' time.","startOfParagraph":false,"startTime":125450},{"duration":2294,"content":"And yet, we're meant\nto be educating them for it.","startOfParagraph":false,"startTime":128000},{"duration":2550,"content":"So the unpredictability,\nI think, is extraordinary.","startOfParagraph":false,"startTime":130318},{"duration":3428,"content":"And the third part of this\nis that we've all agreed, nonetheless,","startOfParagraph":true,"startTime":132892},{"duration":5305,"content":"on the really extraordinary\ncapacities that children have --","startOfParagraph":false,"startTime":136344},{"duration":2335,"content":"their capacities for innovation.","startOfParagraph":false,"startTime":141673},{"duration":2789,"content":"I mean, Sirena last night\nwas a marvel, wasn't she?","startOfParagraph":false,"startTime":144032},{"duration":1670,"content":"Just seeing what she could do.","startOfParagraph":false,"startTime":146845},{"duration":5549,"content":"And she's exceptional, but I think\nshe's not, so to speak,","startOfParagraph":false,"startTime":148539},{"duration":2905,"content":"exceptional in the whole of childhood.","startOfParagraph":false,"startTime":154112},{"duration":2831,"content":"What you have there is a person\nof extraordinary dedication","startOfParagraph":false,"startTime":157041},{"duration":1171,"content":"who found a talent.","startOfParagraph":false,"startTime":159896},{"duration":2586,"content":"And my contention is,\nall kids have tremendous talents,","startOfParagraph":false,"startTime":161091},{"duration":2394,"content":"and we squander them, pretty ruthlessly.","startOfParagraph":false,"startTime":163701},{"duration":1857,"content":"So I want to talk about education,","startOfParagraph":true,"startTime":166119},{"duration":1872,"content":"and I want to talk about creativity.","startOfParagraph":false,"startTime":168000},{"duration":6096,"content":"My contention is that creativity now\nis as important in education as literacy,","startOfParagraph":false,"startTime":169896},{"duration":2787,"content":"and we should treat it\nwith the same status.","startOfParagraph":false,"startTime":176016},{"duration":1112,"content":"(Applause)","startOfParagraph":true,"startTime":178827},{"duration":1189,"content":"Thank you.","startOfParagraph":true,"startTime":179963},{"duration":4285,"content":"(Applause)","startOfParagraph":true,"startTime":181176},{"duration":2286,"content":"That was it, by the way.\nThank you very much.","startOfParagraph":true,"startTime":185485},{"duration":2115,"content":"(Laughter)","startOfParagraph":true,"startTime":187795},{"duration":1677,"content":"So, 15 minutes left.","startOfParagraph":true,"startTime":189934},{"duration":3157,"content":"(Laughter)","startOfParagraph":true,"startTime":191635},{"duration":1671,"content":"\"Well, I was born ... \"","startOfParagraph":true,"startTime":194816},{"duration":3471,"content":"(Laughter)","startOfParagraph":true,"startTime":196511},{"duration":2650,"content":"I heard a great story recently --\nI love telling it --","startOfParagraph":true,"startTime":200006},{"duration":2371,"content":"of a little girl\nwho was in a drawing lesson.","startOfParagraph":false,"startTime":202680},{"duration":2175,"content":"She was six, and she was\nat the back, drawing,","startOfParagraph":false,"startTime":205075},{"duration":2760,"content":"and the teacher said this girl\nhardly ever paid attention,","startOfParagraph":false,"startTime":207274},{"duration":1786,"content":"and in this drawing lesson, she did.","startOfParagraph":false,"startTime":210058},{"duration":1340,"content":"The teacher was fascinated.","startOfParagraph":false,"startTime":211868},{"duration":2789,"content":"She went over to her,\nand she said, \"What are you drawing?\"","startOfParagraph":false,"startTime":213232},{"duration":2491,"content":"And the girl said,\n\"I'm drawing a picture of God.\"","startOfParagraph":false,"startTime":216045},{"duration":3318,"content":"And the teacher said, \"But nobody\nknows what God looks like.\"","startOfParagraph":false,"startTime":219642},{"duration":2088,"content":"And the girl said,\n\"They will in a minute.\"","startOfParagraph":false,"startTime":222984},{"duration":6782,"content":"(Laughter)","startOfParagraph":true,"startTime":225096},{"duration":2727,"content":"When my son was four in England --","startOfParagraph":true,"startTime":236662},{"duration":2191,"content":"actually, he was four\neverywhere, to be honest.","startOfParagraph":false,"startTime":239413},{"duration":1752,"content":"(Laughter)","startOfParagraph":true,"startTime":241628},{"duration":3387,"content":"If we're being strict about it,\nwherever he went, he was four that year.","startOfParagraph":true,"startTime":243404},{"duration":2638,"content":"He was in the Nativity play.\nDo you remember the story?","startOfParagraph":false,"startTime":246815},{"duration":1219,"content":"(Laughter)","startOfParagraph":true,"startTime":249477},{"duration":1827,"content":"No, it was big, it was a big story.","startOfParagraph":true,"startTime":250720},{"duration":2305,"content":"Mel Gibson did the sequel,\nyou may have seen it.","startOfParagraph":false,"startTime":252571},{"duration":1261,"content":"(Laughter)","startOfParagraph":true,"startTime":254900},{"duration":1561,"content":"\"Nativity II.\"","startOfParagraph":true,"startTime":256185},{"duration":3884,"content":"But James got the part of Joseph,\nwhich we were thrilled about.","startOfParagraph":false,"startTime":257770},{"duration":2906,"content":"We considered this to be\none of the lead parts.","startOfParagraph":false,"startTime":261678},{"duration":2487,"content":"We had the place crammed\nfull of agents in T-shirts:","startOfParagraph":false,"startTime":264608},{"duration":1414,"content":"\"James Robinson IS Joseph!\"","startOfParagraph":false,"startTime":267119},{"duration":1033,"content":"(Laughter)","startOfParagraph":false,"startTime":268557},{"duration":3628,"content":"He didn't have to speak, but you know\nthe bit where the three kings come in?","startOfParagraph":false,"startTime":269614},{"duration":2685,"content":"They come in bearing gifts,\ngold, frankincense and myrrh.","startOfParagraph":false,"startTime":273266},{"duration":1158,"content":"This really happened.","startOfParagraph":false,"startTime":275975},{"duration":3116,"content":"We were sitting there, and I think\nthey just went out of sequence,","startOfParagraph":false,"startTime":277157},{"duration":2579,"content":"because we talked to the little boy\nafterward and said,","startOfParagraph":false,"startTime":280297},{"duration":2796,"content":"\"You OK with that?\" They said,\n\"Yeah, why? Was that wrong?\"","startOfParagraph":false,"startTime":282900},{"duration":1156,"content":"They just switched.","startOfParagraph":false,"startTime":285720},{"duration":3310,"content":"The three boys came in, four-year-olds\nwith tea towels on their heads.","startOfParagraph":false,"startTime":286900},{"duration":3322,"content":"They put these boxes down, and the first\nboy said, \"I bring you gold.\"","startOfParagraph":false,"startTime":290234},{"duration":2274,"content":"And the second boy said,\n\"I bring you myrrh.\"","startOfParagraph":false,"startTime":293580},{"duration":2082,"content":"And the third boy said, \"Frank sent this.\"","startOfParagraph":false,"startTime":295878},{"duration":5477,"content":"(Laughter)","startOfParagraph":true,"startTime":297984},{"duration":3090,"content":"What these things have in common\nis that kids will take a chance.","startOfParagraph":true,"startTime":310711},{"duration":3482,"content":"If they don't know, they'll have a go.","startOfParagraph":false,"startTime":313825},{"duration":3029,"content":"Am I right? They're not\nfrightened of being wrong.","startOfParagraph":false,"startTime":317331},{"duration":3507,"content":"I don't mean to say that being wrong\nis the same thing as being creative.","startOfParagraph":false,"startTime":320924},{"duration":3090,"content":"What we do know is,\nif you're not prepared to be wrong,","startOfParagraph":false,"startTime":324886},{"duration":2367,"content":"you'll never come up\nwith anything original --","startOfParagraph":false,"startTime":328000},{"duration":2580,"content":"if you're not prepared to be wrong.","startOfParagraph":false,"startTime":330391},{"duration":4443,"content":"And by the time they get to be adults,\nmost kids have lost that capacity.","startOfParagraph":false,"startTime":332995},{"duration":2464,"content":"They have become\nfrightened of being wrong.","startOfParagraph":false,"startTime":337462},{"duration":1690,"content":"And we run our companies like this.","startOfParagraph":false,"startTime":339950},{"duration":1652,"content":"We stigmatize mistakes.","startOfParagraph":false,"startTime":341664},{"duration":2302,"content":"And we're now running\nnational education systems","startOfParagraph":false,"startTime":343340},{"duration":2539,"content":"where mistakes are the worst\nthing you can make.","startOfParagraph":false,"startTime":345666},{"duration":3108,"content":"And the result is that\nwe are educating people","startOfParagraph":false,"startTime":348800},{"duration":2342,"content":"out of their creative capacities.","startOfParagraph":false,"startTime":351932},{"duration":4427,"content":"Picasso once said this, he said\nthat all children are born artists.","startOfParagraph":true,"startTime":354298},{"duration":3222,"content":"The problem is to remain\nan artist as we grow up.","startOfParagraph":false,"startTime":358749},{"duration":3232,"content":"I believe this passionately,\nthat we don't grow into creativity,","startOfParagraph":false,"startTime":361995},{"duration":1705,"content":"we grow out of it.","startOfParagraph":false,"startTime":365251},{"duration":1883,"content":"Or rather, we get educated out of it.","startOfParagraph":false,"startTime":366980},{"duration":1903,"content":"So why is this?","startOfParagraph":false,"startTime":369607},{"duration":2783,"content":"I lived in Stratford-on-Avon\nuntil about five years ago.","startOfParagraph":true,"startTime":372124},{"duration":2253,"content":"In fact, we moved from Stratford\nto Los Angeles.","startOfParagraph":false,"startTime":374931},{"duration":2624,"content":"So you can imagine\nwhat a seamless transition this was.","startOfParagraph":false,"startTime":377912},{"duration":1416,"content":"(Laughter)","startOfParagraph":true,"startTime":380560},{"duration":2376,"content":"Actually, we lived in a place\ncalled Snitterfield,","startOfParagraph":true,"startTime":382000},{"duration":1251,"content":"just outside Stratford,","startOfParagraph":false,"startTime":384400},{"duration":2635,"content":"which is where\nShakespeare's father was born.","startOfParagraph":false,"startTime":385675},{"duration":2123,"content":"Are you struck by a new thought? I was.","startOfParagraph":false,"startTime":388334},{"duration":2595,"content":"You don't think of Shakespeare\nhaving a father, do you?","startOfParagraph":false,"startTime":390481},{"duration":1373,"content":"Do you?","startOfParagraph":false,"startTime":393100},{"duration":2891,"content":"Because you don't think\nof Shakespeare being a child, do you?","startOfParagraph":false,"startTime":394497},{"duration":1264,"content":"Shakespeare being seven?","startOfParagraph":false,"startTime":397412},{"duration":1176,"content":"I never thought of it.","startOfParagraph":false,"startTime":398700},{"duration":1692,"content":"I mean, he was seven at some point.","startOfParagraph":false,"startTime":399900},{"duration":2266,"content":"He was in somebody's\nEnglish class, wasn't he?","startOfParagraph":false,"startTime":401616},{"duration":6787,"content":"(Laughter)","startOfParagraph":true,"startTime":403906},{"duration":1329,"content":"How annoying would that be?","startOfParagraph":true,"startTime":410717},{"duration":3000,"content":"(Laughter)","startOfParagraph":true,"startTime":412070},{"duration":1340,"content":"\"Must try harder.\"","startOfParagraph":true,"startTime":419939},{"duration":3400,"content":"(Laughter)","startOfParagraph":true,"startTime":421303},{"duration":2981,"content":"Being sent to bed by his dad,\nto Shakespeare, \"Go to bed, now!\"","startOfParagraph":true,"startTime":425559},{"duration":1158,"content":"To William Shakespeare.","startOfParagraph":false,"startTime":428564},{"duration":1271,"content":"\"And put the pencil down!\"","startOfParagraph":false,"startTime":429746},{"duration":1075,"content":"(Laughter)","startOfParagraph":true,"startTime":431041},{"duration":1477,"content":"\"And stop speaking like that.\"","startOfParagraph":true,"startTime":432140},{"duration":3579,"content":"(Laughter)","startOfParagraph":true,"startTime":433641},{"duration":1324,"content":"\"It's confusing everybody.\"","startOfParagraph":true,"startTime":437244},{"duration":5270,"content":"(Laughter)","startOfParagraph":true,"startTime":438592},{"duration":5186,"content":"Anyway, we moved\nfrom Stratford to Los Angeles,","startOfParagraph":true,"startTime":443886},{"duration":2476,"content":"and I just want to say a word\nabout the transition.","startOfParagraph":false,"startTime":449096},{"duration":1802,"content":"Actually, my son didn't want to come.","startOfParagraph":false,"startTime":451596},{"duration":2395,"content":"I've got two kids;\nhe's 21 now, my daughter's 16.","startOfParagraph":false,"startTime":453422},{"duration":2203,"content":"He didn't want to come to Los Angeles.","startOfParagraph":false,"startTime":455841},{"duration":3788,"content":"He loved it, but he had\na girlfriend in England.","startOfParagraph":false,"startTime":458068},{"duration":2857,"content":"This was the love of his life, Sarah.","startOfParagraph":false,"startTime":461880},{"duration":1375,"content":"He'd known her for a month.","startOfParagraph":false,"startTime":464761},{"duration":1350,"content":"(Laughter)","startOfParagraph":true,"startTime":466160},{"duration":3279,"content":"Mind you, they'd had\ntheir fourth anniversary,","startOfParagraph":true,"startTime":467534},{"duration":1936,"content":"because it's a long time when you're 16.","startOfParagraph":false,"startTime":470837},{"duration":1641,"content":"He was really upset on the plane.","startOfParagraph":false,"startTime":472797},{"duration":2407,"content":"He said, \"I'll never find\nanother girl like Sarah.\"","startOfParagraph":false,"startTime":474462},{"duration":2314,"content":"And we were rather pleased\nabout that, frankly --","startOfParagraph":false,"startTime":476893},{"duration":4233,"content":"(Laughter)","startOfParagraph":true,"startTime":479231},{"duration":2946,"content":"because she was the main reason\nwe were leaving the country.","startOfParagraph":true,"startTime":487434},{"duration":3000,"content":"(Laughter)","startOfParagraph":true,"startTime":490404},{"duration":2362,"content":"But something strikes you\nwhen you move to America","startOfParagraph":true,"startTime":496141},{"duration":1367,"content":"and travel around the world:","startOfParagraph":false,"startTime":498527},{"duration":3647,"content":"every education system on earth\nhas the same hierarchy of subjects.","startOfParagraph":false,"startTime":499918},{"duration":1903,"content":"Every one. Doesn't matter where you go.","startOfParagraph":false,"startTime":503589},{"duration":2270,"content":"You'd think it would be\notherwise, but it isn't.","startOfParagraph":false,"startTime":505516},{"duration":2981,"content":"At the top are mathematics and languages,\nthen the humanities.","startOfParagraph":false,"startTime":507810},{"duration":2291,"content":"At the bottom are the arts.\nEverywhere on earth.","startOfParagraph":false,"startTime":510815},{"duration":4365,"content":"And in pretty much every system, too,\nthere's a hierarchy within the arts.","startOfParagraph":false,"startTime":513130},{"duration":2857,"content":"Art and music are normally given\na higher status in schools","startOfParagraph":false,"startTime":517519},{"duration":1428,"content":"than drama and dance.","startOfParagraph":false,"startTime":520400},{"duration":2107,"content":"There isn't an education\nsystem on the planet","startOfParagraph":false,"startTime":521852},{"duration":1919,"content":"that teaches dance every day to children","startOfParagraph":false,"startTime":523983},{"duration":1650,"content":"the way we teach them mathematics.","startOfParagraph":false,"startTime":525926},{"duration":1158,"content":"Why?","startOfParagraph":false,"startTime":527600},{"duration":1167,"content":"Why not?","startOfParagraph":false,"startTime":528782},{"duration":1594,"content":"I think this is rather important.","startOfParagraph":false,"startTime":529973},{"duration":2264,"content":"I think math is very important,\nbut so is dance.","startOfParagraph":false,"startTime":531591},{"duration":2880,"content":"Children dance all the time\nif they're allowed to, we all do.","startOfParagraph":false,"startTime":533879},{"duration":2450,"content":"We all have bodies, don't we?\nDid I miss a meeting?","startOfParagraph":false,"startTime":536783},{"duration":3364,"content":"(Laughter)","startOfParagraph":true,"startTime":539257},{"duration":2321,"content":"Truthfully, what happens is,\nas children grow up,","startOfParagraph":true,"startTime":542645},{"duration":2714,"content":"we start to educate them progressively\nfrom the waist up.","startOfParagraph":false,"startTime":544990},{"duration":1626,"content":"And then we focus on their heads.","startOfParagraph":false,"startTime":547728},{"duration":1490,"content":"And slightly to one side.","startOfParagraph":false,"startTime":549378},{"duration":2071,"content":"If you were to visit education as an alien","startOfParagraph":true,"startTime":552044},{"duration":2981,"content":"and say \"What's it for, public education?\"","startOfParagraph":false,"startTime":554139},{"duration":2727,"content":"I think you'd have to conclude,\nif you look at the output,","startOfParagraph":false,"startTime":557144},{"duration":1357,"content":"who really succeeds by this,","startOfParagraph":false,"startTime":559895},{"duration":1700,"content":"who does everything they should,","startOfParagraph":false,"startTime":561276},{"duration":2731,"content":"who gets all the brownie points,\nwho are the winners --","startOfParagraph":false,"startTime":563000},{"duration":3238,"content":"I think you'd have to conclude\nthe whole purpose of public education","startOfParagraph":false,"startTime":565755},{"duration":1198,"content":"throughout the world","startOfParagraph":false,"startTime":569017},{"duration":1979,"content":"is to produce university professors.","startOfParagraph":false,"startTime":570239},{"duration":1168,"content":"Isn't it?","startOfParagraph":false,"startTime":572718},{"duration":1984,"content":"They're the people who come out the top.","startOfParagraph":false,"startTime":573910},{"duration":1819,"content":"And I used to be one, so there.","startOfParagraph":false,"startTime":575918},{"duration":3697,"content":"(Laughter)","startOfParagraph":true,"startTime":577761},{"duration":1600,"content":"And I like university professors,","startOfParagraph":true,"startTime":581482},{"duration":1915,"content":"but, you know, we shouldn't hold them up","startOfParagraph":false,"startTime":583106},{"duration":2931,"content":"as the high-water mark\nof all human achievement.","startOfParagraph":false,"startTime":585045},{"duration":2113,"content":"They're just a form of life.","startOfParagraph":false,"startTime":588000},{"duration":1423,"content":"Another form of life.","startOfParagraph":false,"startTime":590137},{"duration":1397,"content":"But they're rather curious.","startOfParagraph":false,"startTime":591584},{"duration":1964,"content":"And I say this out of affection for them:","startOfParagraph":false,"startTime":593005},{"duration":2075,"content":"there's something curious\nabout professors.","startOfParagraph":false,"startTime":594993},{"duration":3746,"content":"In my experience -- not all of them,\nbut typically -- they live in their heads.","startOfParagraph":false,"startTime":597092},{"duration":2143,"content":"They live up there\nand slightly to one side.","startOfParagraph":false,"startTime":600862},{"duration":3436,"content":"They're disembodied, you know,\nin a kind of literal way.","startOfParagraph":false,"startTime":603495},{"duration":3150,"content":"They look upon their body as a form\nof transport for their heads.","startOfParagraph":false,"startTime":606955},{"duration":6047,"content":"(Laughter)","startOfParagraph":true,"startTime":610129},{"duration":1377,"content":"Don't they?","startOfParagraph":true,"startTime":616200},{"duration":2145,"content":"It's a way of getting\ntheir head to meetings.","startOfParagraph":false,"startTime":617601},{"duration":5228,"content":"(Laughter)","startOfParagraph":true,"startTime":619770},{"duration":3922,"content":"If you want real evidence\nof out-of-body experiences, by the way,","startOfParagraph":true,"startTime":625022},{"duration":3475,"content":"get yourself along to a residential\nconference of senior academics","startOfParagraph":false,"startTime":628968},{"duration":2351,"content":"and pop into the discotheque\non the final night.","startOfParagraph":false,"startTime":632467},{"duration":2612,"content":"(Laughter)","startOfParagraph":true,"startTime":634842},{"duration":1356,"content":"And there, you will see it.","startOfParagraph":true,"startTime":637478},{"duration":4493,"content":"Grown men and women\nwrithing uncontrollably, off the beat.","startOfParagraph":false,"startTime":638858},{"duration":2492,"content":"(Laughter)","startOfParagraph":true,"startTime":643375},{"duration":3325,"content":"Waiting until it ends, so they can\ngo home and write a paper about it.","startOfParagraph":true,"startTime":645891},{"duration":1981,"content":"(Laughter)","startOfParagraph":true,"startTime":649240},{"duration":3861,"content":"Our education system is predicated\non the idea of academic ability.","startOfParagraph":true,"startTime":651245},{"duration":1171,"content":"And there's a reason.","startOfParagraph":false,"startTime":655130},{"duration":3629,"content":"Around the world, there were\nno public systems of education,","startOfParagraph":false,"startTime":656325},{"duration":2107,"content":"really, before the 19th century.","startOfParagraph":false,"startTime":659978},{"duration":3247,"content":"They all came into being\nto meet the needs of industrialism.","startOfParagraph":false,"startTime":662109},{"duration":2052,"content":"So the hierarchy is rooted on two ideas.","startOfParagraph":false,"startTime":665380},{"duration":4562,"content":"Number one, that the most useful\nsubjects for work are at the top.","startOfParagraph":true,"startTime":667456},{"duration":3033,"content":"So you were probably steered benignly away\nfrom things at school","startOfParagraph":false,"startTime":672042},{"duration":1152,"content":"when you were a kid,","startOfParagraph":false,"startTime":675099},{"duration":1153,"content":"things you liked,","startOfParagraph":false,"startTime":676275},{"duration":2442,"content":"on the grounds you would never\nget a job doing that.","startOfParagraph":false,"startTime":677452},{"duration":1151,"content":"Is that right?","startOfParagraph":false,"startTime":679918},{"duration":2412,"content":"\"Don't do music, you're not\ngoing to be a musician;","startOfParagraph":false,"startTime":681093},{"duration":1851,"content":"don't do art, you won't be an artist.\"","startOfParagraph":false,"startTime":683529},{"duration":2746,"content":"Benign advice -- now, profoundly mistaken.","startOfParagraph":false,"startTime":685404},{"duration":2145,"content":"The whole world\nis engulfed in a revolution.","startOfParagraph":false,"startTime":688174},{"duration":2097,"content":"And the second is academic ability,","startOfParagraph":true,"startTime":690343},{"duration":2819,"content":"which has really come to dominate\nour view of intelligence,","startOfParagraph":false,"startTime":692464},{"duration":2739,"content":"because the universities design\nthe system in their image.","startOfParagraph":false,"startTime":695307},{"duration":1151,"content":"If you think of it,","startOfParagraph":false,"startTime":698070},{"duration":3664,"content":"the whole system of public education\naround the world is a protracted process","startOfParagraph":false,"startTime":699245},{"duration":1151,"content":"of university entrance.","startOfParagraph":false,"startTime":702933},{"duration":2293,"content":"And the consequence is\nthat many highly talented,","startOfParagraph":false,"startTime":704108},{"duration":2518,"content":"brilliant, creative people\nthink they're not,","startOfParagraph":false,"startTime":706425},{"duration":2133,"content":"because the thing\nthey were good at at school","startOfParagraph":false,"startTime":708967},{"duration":2302,"content":"wasn't valued,\nor was actually stigmatized.","startOfParagraph":false,"startTime":711124},{"duration":2229,"content":"And I think we can't afford\nto go on that way.","startOfParagraph":false,"startTime":713450},{"duration":2287,"content":"In the next 30 years, according to UNESCO,","startOfParagraph":true,"startTime":715703},{"duration":3406,"content":"more people worldwide will be\ngraduating through education","startOfParagraph":false,"startTime":718014},{"duration":2195,"content":"than since the beginning of history.","startOfParagraph":false,"startTime":721444},{"duration":1157,"content":"More people.","startOfParagraph":false,"startTime":723663},{"duration":2921,"content":"And it's the combination\nof all the things we've talked about:","startOfParagraph":false,"startTime":724844},{"duration":2393,"content":"technology and its\ntransformational effect on work,","startOfParagraph":false,"startTime":727789},{"duration":2478,"content":"and demography and the huge\nexplosion in population.","startOfParagraph":false,"startTime":730206},{"duration":2437,"content":"Suddenly, degrees aren't worth anything.","startOfParagraph":true,"startTime":732708},{"duration":1677,"content":"Isn't that true?","startOfParagraph":false,"startTime":735169},{"duration":2981,"content":"When I was a student,\nif you had a degree, you had a job.","startOfParagraph":false,"startTime":736870},{"duration":2798,"content":"If you didn't have a job,\nit's because you didn't want one.","startOfParagraph":false,"startTime":739875},{"duration":2334,"content":"And I didn't want one, frankly.","startOfParagraph":false,"startTime":742697},{"duration":1591,"content":"(Laughter)","startOfParagraph":true,"startTime":745055},{"duration":3805,"content":"But now kids with degrees\nare often heading home","startOfParagraph":true,"startTime":746670},{"duration":1794,"content":"to carry on playing video games,","startOfParagraph":false,"startTime":750499},{"duration":3048,"content":"because you need an MA\nwhere the previous job required a BA,","startOfParagraph":false,"startTime":752317},{"duration":1787,"content":"and now you need a PhD for the other.","startOfParagraph":false,"startTime":755389},{"duration":1776,"content":"It's a process of academic inflation.","startOfParagraph":false,"startTime":757200},{"duration":3756,"content":"And it indicates the whole structure\nof education is shifting beneath our feet.","startOfParagraph":false,"startTime":759000},{"duration":2542,"content":"We need to radically rethink\nour view of intelligence.","startOfParagraph":false,"startTime":762780},{"duration":1924,"content":"We know three things about intelligence.","startOfParagraph":true,"startTime":765346},{"duration":1151,"content":"One, it's diverse.","startOfParagraph":false,"startTime":767294},{"duration":2981,"content":"We think about the world in all the ways\nthat we experience it.","startOfParagraph":false,"startTime":768469},{"duration":2977,"content":"We think visually, we think in sound,\nwe think kinesthetically.","startOfParagraph":false,"startTime":771474},{"duration":2321,"content":"We think in abstract terms,\nwe think in movement.","startOfParagraph":false,"startTime":774475},{"duration":1996,"content":"Secondly, intelligence is dynamic.","startOfParagraph":false,"startTime":776820},{"duration":2303,"content":"If you look at the interactions\nof a human brain,","startOfParagraph":false,"startTime":779673},{"duration":3023,"content":"as we heard yesterday\nfrom a number of presentations,","startOfParagraph":false,"startTime":782000},{"duration":2158,"content":"intelligence is wonderfully interactive.","startOfParagraph":false,"startTime":785047},{"duration":2238,"content":"The brain isn't divided into compartments.","startOfParagraph":false,"startTime":787229},{"duration":1574,"content":"In fact, creativity --","startOfParagraph":false,"startTime":789872},{"duration":4020,"content":"which I define as the process of having\noriginal ideas that have value --","startOfParagraph":false,"startTime":791470},{"duration":1930,"content":"more often than not comes about","startOfParagraph":false,"startTime":795514},{"duration":3557,"content":"through the interaction of different\ndisciplinary ways of seeing things.","startOfParagraph":false,"startTime":797468},{"duration":3631,"content":"By the way, there's a shaft of nerves\nthat joins the two halves of the brain,","startOfParagraph":true,"startTime":802472},{"duration":1298,"content":"called the corpus callosum.","startOfParagraph":false,"startTime":806127},{"duration":1221,"content":"It's thicker in women.","startOfParagraph":false,"startTime":807449},{"duration":1723,"content":"Following off from Helen yesterday,","startOfParagraph":false,"startTime":809471},{"duration":3011,"content":"this is probably why women\nare better at multitasking.","startOfParagraph":false,"startTime":811218},{"duration":1825,"content":"Because you are, aren't you?","startOfParagraph":false,"startTime":814253},{"duration":3334,"content":"There's a raft of research,\nbut I know it from my personal life.","startOfParagraph":false,"startTime":816102},{"duration":2935,"content":"If my wife is cooking a meal\nat home, which is not often ...","startOfParagraph":false,"startTime":819865},{"duration":1166,"content":"thankfully.","startOfParagraph":false,"startTime":824224},{"duration":2690,"content":"(Laughter)","startOfParagraph":true,"startTime":825414},{"duration":1452,"content":"No, she's good at some things.","startOfParagraph":true,"startTime":828128},{"duration":2895,"content":"But if she's cooking,\nshe's dealing with people on the phone,","startOfParagraph":false,"startTime":829604},{"duration":2647,"content":"she's talking to the kids,\nshe's painting the ceiling --","startOfParagraph":false,"startTime":832523},{"duration":1015,"content":"(Laughter)","startOfParagraph":true,"startTime":835194},{"duration":2025,"content":"she's doing open-heart surgery over here.","startOfParagraph":true,"startTime":836233},{"duration":2998,"content":"If I'm cooking, the door\nis shut, the kids are out,","startOfParagraph":false,"startTime":838282},{"duration":1239,"content":"the phone's on the hook,","startOfParagraph":false,"startTime":841304},{"duration":1690,"content":"if she comes in, I get annoyed.","startOfParagraph":false,"startTime":842567},{"duration":2790,"content":"I say, \"Terry, please,\nI'm trying to fry an egg in here.\"","startOfParagraph":false,"startTime":844281},{"duration":6730,"content":"(Laughter)","startOfParagraph":true,"startTime":847095},{"duration":1200,"content":"\"Give me a break.\"","startOfParagraph":true,"startTime":854254},{"duration":1720,"content":"(Laughter)","startOfParagraph":true,"startTime":855478},{"duration":2499,"content":"Actually, do you know\nthat old philosophical thing,","startOfParagraph":true,"startTime":857222},{"duration":3483,"content":"\"If a tree falls in a forest,\nand nobody hears it, did it happen?\"","startOfParagraph":false,"startTime":859745},{"duration":1329,"content":"Remember that old chestnut?","startOfParagraph":false,"startTime":863252},{"duration":2910,"content":"I saw a great T-shirt\nrecently, which said,","startOfParagraph":false,"startTime":864605},{"duration":3437,"content":"\"If a man speaks his mind in a forest,\nand no woman hears him,","startOfParagraph":false,"startTime":867539},{"duration":1396,"content":"is he still wrong?\"","startOfParagraph":false,"startTime":871000},{"duration":5606,"content":"(Laughter)","startOfParagraph":true,"startTime":872420},{"duration":2039,"content":"And the third thing about intelligence is,","startOfParagraph":true,"startTime":880089},{"duration":1369,"content":"it's distinct.","startOfParagraph":false,"startTime":882152},{"duration":2504,"content":"I'm doing a new book at the moment\ncalled \"Epiphany,\"","startOfParagraph":false,"startTime":884114},{"duration":2441,"content":"which is based on a series\nof interviews with people","startOfParagraph":false,"startTime":886642},{"duration":1864,"content":"about how they discovered their talent.","startOfParagraph":false,"startTime":889107},{"duration":2121,"content":"I'm fascinated by\nhow people got to be there.","startOfParagraph":false,"startTime":890995},{"duration":3191,"content":"It's really prompted by a conversation\nI had with a wonderful woman","startOfParagraph":false,"startTime":893140},{"duration":2677,"content":"who maybe most people\nhave never heard of, Gillian Lynne.","startOfParagraph":false,"startTime":896355},{"duration":1596,"content":"Have you heard of her? Some have.","startOfParagraph":false,"startTime":899056},{"duration":2452,"content":"She's a choreographer,\nand everybody knows her work.","startOfParagraph":false,"startTime":900676},{"duration":2016,"content":"She did \"Cats\" and \"Phantom of the Opera.\"","startOfParagraph":false,"startTime":903152},{"duration":1151,"content":"She's wonderful.","startOfParagraph":false,"startTime":905192},{"duration":2947,"content":"I used to be on the board\nof The Royal Ballet, as you can see.","startOfParagraph":false,"startTime":906367},{"duration":1929,"content":"(Laughter)","startOfParagraph":true,"startTime":909338},{"duration":3525,"content":"Gillian and I had lunch one day.\nI said, \"How did you get to be a dancer?\"","startOfParagraph":true,"startTime":911291},{"duration":1151,"content":"It was interesting.","startOfParagraph":false,"startTime":914840},{"duration":2247,"content":"When she was at school,\nshe was really hopeless.","startOfParagraph":false,"startTime":916015},{"duration":2789,"content":"And the school, in the '30s,\nwrote to her parents and said,","startOfParagraph":false,"startTime":918286},{"duration":2035,"content":"\"We think Gillian\nhas a learning disorder.\"","startOfParagraph":false,"startTime":921099},{"duration":2098,"content":"She couldn't concentrate;\nshe was fidgeting.","startOfParagraph":false,"startTime":923158},{"duration":1877,"content":"I think now they'd say she had ADHD.","startOfParagraph":false,"startTime":925280},{"duration":1299,"content":"Wouldn't you?","startOfParagraph":false,"startTime":927181},{"duration":4177,"content":"But this was the 1930s, and ADHD\nhadn't been invented at this point.","startOfParagraph":false,"startTime":928504},{"duration":2040,"content":"It wasn't an available condition.","startOfParagraph":false,"startTime":932705},{"duration":3215,"content":"(Laughter)","startOfParagraph":true,"startTime":934769},{"duration":2042,"content":"People weren't aware they could have that.","startOfParagraph":true,"startTime":938008},{"duration":2425,"content":"(Laughter)","startOfParagraph":true,"startTime":940074},{"duration":4176,"content":"Anyway, she went to see this specialist.","startOfParagraph":true,"startTime":942523},{"duration":3707,"content":"So, this oak-paneled room,\nand she was there with her mother,","startOfParagraph":false,"startTime":946723},{"duration":2327,"content":"and she was led and sat\non this chair at the end,","startOfParagraph":false,"startTime":950454},{"duration":1945,"content":"and she sat on her hands for 20 minutes,","startOfParagraph":false,"startTime":952805},{"duration":1681,"content":"while this man talked to her mother","startOfParagraph":false,"startTime":954774},{"duration":2464,"content":"about all the problems\nGillian was having at school,","startOfParagraph":false,"startTime":956479},{"duration":3549,"content":"because she was disturbing people,\nher homework was always late, and so on.","startOfParagraph":false,"startTime":958967},{"duration":1151,"content":"Little kid of eight.","startOfParagraph":false,"startTime":962540},{"duration":2911,"content":"In the end, the doctor went\nand sat next to Gillian and said,","startOfParagraph":false,"startTime":963715},{"duration":2713,"content":"\"I've listened to all these\nthings your mother's told me.","startOfParagraph":false,"startTime":966650},{"duration":1594,"content":"I need to speak to her privately.","startOfParagraph":false,"startTime":969387},{"duration":2316,"content":"Wait here. We'll be back.\nWe won't be very long,\"","startOfParagraph":false,"startTime":971005},{"duration":2650,"content":"and they went and left her.","startOfParagraph":false,"startTime":973345},{"duration":1640,"content":"But as they went out of the room,","startOfParagraph":true,"startTime":976019},{"duration":2856,"content":"he turned on the radio\nthat was sitting on his desk.","startOfParagraph":false,"startTime":977683},{"duration":1638,"content":"And when they got out of the room,","startOfParagraph":false,"startTime":980563},{"duration":2378,"content":"he said to her mother,\n\"Just stand and watch her.\"","startOfParagraph":false,"startTime":982225},{"duration":2512,"content":"And the minute they left the room,","startOfParagraph":false,"startTime":984627},{"duration":2595,"content":"she was on her feet, moving to the music.","startOfParagraph":false,"startTime":987163},{"duration":3503,"content":"And they watched for a few minutes,\nand he turned to her mother and said,","startOfParagraph":false,"startTime":989782},{"duration":1979,"content":"\"Mrs. Lynne, Gillian isn't sick.","startOfParagraph":false,"startTime":993309},{"duration":1664,"content":"She's a dancer.","startOfParagraph":false,"startTime":995312},{"duration":1386,"content":"Take her to a dance school.\"","startOfParagraph":false,"startTime":998338},{"duration":1228,"content":"I said, \"What happened?\"","startOfParagraph":true,"startTime":999748},{"duration":2976,"content":"She said, \"She did. I can't tell you\nhow wonderful it was.","startOfParagraph":false,"startTime":1001000},{"duration":2829,"content":"We walked in this room,\nand it was full of people like me --","startOfParagraph":false,"startTime":1004000},{"duration":2222,"content":"people who couldn't sit still,","startOfParagraph":false,"startTime":1006853},{"duration":2907,"content":"people who had to move to think.\"","startOfParagraph":false,"startTime":1009099},{"duration":1832,"content":"Who had to move to think.","startOfParagraph":false,"startTime":1012030},{"duration":3610,"content":"They did ballet, they did tap, jazz;\nthey did modern; they did contemporary.","startOfParagraph":false,"startTime":1013886},{"duration":2746,"content":"She was eventually auditioned\nfor the Royal Ballet School.","startOfParagraph":false,"startTime":1017520},{"duration":3253,"content":"She became a soloist; she had\na wonderful career at the Royal Ballet.","startOfParagraph":false,"startTime":1020290},{"duration":2555,"content":"She eventually graduated\nfrom the Royal Ballet School,","startOfParagraph":false,"startTime":1023567},{"duration":1928,"content":"founded the Gillian Lynne Dance Company,","startOfParagraph":false,"startTime":1026146},{"duration":1237,"content":"met Andrew Lloyd Webber.","startOfParagraph":false,"startTime":1028098},{"duration":1296,"content":"She's been responsible for","startOfParagraph":false,"startTime":1029359},{"duration":3148,"content":"some of the most successful\nmusical theater productions in history,","startOfParagraph":false,"startTime":1030679},{"duration":1596,"content":"she's given pleasure to millions,","startOfParagraph":false,"startTime":1033851},{"duration":1407,"content":"and she's a multimillionaire.","startOfParagraph":false,"startTime":1035471},{"duration":3710,"content":"Somebody else might have put her\non medication and told her to calm down.","startOfParagraph":false,"startTime":1036902},{"duration":6782,"content":"(Applause)","startOfParagraph":true,"startTime":1040636},{"duration":1573,"content":"What I think it comes to is this:","startOfParagraph":true,"startTime":1048603},{"duration":1776,"content":"Al Gore spoke the other night","startOfParagraph":false,"startTime":1050200},{"duration":4519,"content":"about ecology and the revolution\nthat was triggered by Rachel Carson.","startOfParagraph":false,"startTime":1052000},{"duration":2112,"content":"I believe our only hope for the future","startOfParagraph":false,"startTime":1057257},{"duration":3875,"content":"is to adopt a new conception\nof human ecology,","startOfParagraph":false,"startTime":1059393},{"duration":2527,"content":"one in which we start\nto reconstitute our conception","startOfParagraph":false,"startTime":1063292},{"duration":2261,"content":"of the richness of human capacity.","startOfParagraph":false,"startTime":1065843},{"duration":3371,"content":"Our education system has mined our minds","startOfParagraph":false,"startTime":1068128},{"duration":3441,"content":"in the way that we strip-mine the earth\nfor a particular commodity.","startOfParagraph":false,"startTime":1071523},{"duration":2422,"content":"And for the future, it won't serve us.","startOfParagraph":false,"startTime":1075377},{"duration":2153,"content":"We have to rethink\nthe fundamental principles","startOfParagraph":false,"startTime":1077823},{"duration":2063,"content":"on which we're educating our children.","startOfParagraph":false,"startTime":1080000},{"duration":2674,"content":"There was a wonderful quote\nby Jonas Salk, who said,","startOfParagraph":true,"startTime":1082087},{"duration":5097,"content":"\"If all the insects\nwere to disappear from the Earth,","startOfParagraph":false,"startTime":1084785},{"duration":2783,"content":"within 50 years,\nall life on Earth would end.","startOfParagraph":false,"startTime":1089906},{"duration":3037,"content":"If all human beings\ndisappeared from the Earth,","startOfParagraph":false,"startTime":1093770},{"duration":2634,"content":"within 50 years,\nall forms of life would flourish.\"","startOfParagraph":false,"startTime":1096831},{"duration":1285,"content":"And he's right.","startOfParagraph":false,"startTime":1100378},{"duration":3731,"content":"What TED celebrates is the gift\nof the human imagination.","startOfParagraph":true,"startTime":1102390},{"duration":4234,"content":"We have to be careful now\nthat we use this gift wisely,","startOfParagraph":false,"startTime":1106533},{"duration":3229,"content":"and that we avert some of the scenarios\nthat we've talked about.","startOfParagraph":false,"startTime":1110791},{"duration":3755,"content":"And the only way we'll do it\nis by seeing our creative capacities","startOfParagraph":false,"startTime":1114044},{"duration":1787,"content":"for the richness they are","startOfParagraph":false,"startTime":1117823},{"duration":3182,"content":"and seeing our children\nfor the hope that they are.","startOfParagraph":false,"startTime":1119634},{"duration":2398,"content":"And our task is to educate\ntheir whole being,","startOfParagraph":false,"startTime":1122840},{"duration":1413,"content":"so they can face this future.","startOfParagraph":false,"startTime":1125262},{"duration":2505,"content":"By the way -- we may not see this future,","startOfParagraph":false,"startTime":1126699},{"duration":1563,"content":"but they will.","startOfParagraph":false,"startTime":1129228},{"duration":2718,"content":"And our job is to help them\nmake something of it.","startOfParagraph":false,"startTime":1130815},{"duration":1185,"content":"Thank you very much.","startOfParagraph":true,"startTime":1133557},{"duration":5447,"content":"(Applause)","startOfParagraph":true,"startTime":1134766}],
  zh: [{"duration":7000,"content":"早上好，还好吗?\n很好吧，对不对?","startOfParagraph":true,"startTime":0},{"duration":4000,"content":"我已经飘飘然了!","startOfParagraph":false,"startTime":7000},{"duration":4000,"content":"我要飘走了。(笑声)","startOfParagraph":false,"startTime":11000},{"duration":4000,"content":"这次会议有三个主题","startOfParagraph":false,"startTime":15000},{"duration":4000,"content":"这三个主题贯穿会议始终，并且和","startOfParagraph":false,"startTime":19000},{"duration":2000,"content":"我要谈的内容有关","startOfParagraph":false,"startTime":23000},{"duration":4000,"content":"其中之一就是人类创造力的伟大例证","startOfParagraph":false,"startTime":25000},{"duration":3000,"content":"这些例证已经体现在之前的演讲当中","startOfParagraph":false,"startTime":29000},{"duration":3000,"content":"以及在座各位的身上。\n从这些例证中我们看到了创新的多样化","startOfParagraph":false,"startTime":32000},{"duration":3000,"content":"和多领域。第二点--","startOfParagraph":false,"startTime":35000},{"duration":3000,"content":"这些创新也让我们意识到\n我们不知道未来会发生什么","startOfParagraph":false,"startTime":38000},{"duration":2000,"content":"完全不知道","startOfParagraph":false,"startTime":41000},{"duration":2000,"content":"未来会如何","startOfParagraph":false,"startTime":43000},{"duration":3000,"content":"我对教育感兴趣","startOfParagraph":true,"startTime":45000},{"duration":3000,"content":"事实上，我发现每个人都对教育感兴趣","startOfParagraph":false,"startTime":48000},{"duration":2000,"content":"难道不是吗? 我发现这很有趣","startOfParagraph":false,"startTime":51000},{"duration":3000,"content":"如果你参加一个晚宴，你说","startOfParagraph":false,"startTime":53000},{"duration":3000,"content":"你在教育部门工作","startOfParagraph":false,"startTime":56000},{"duration":7000,"content":"坦白的讲，如果你在教育部门工作，\n事实上你不会经常参加晚宴，","startOfParagraph":false,"startTime":59000},{"duration":3000,"content":"(笑声) 所以你不会被问及你是做哪行的。","startOfParagraph":false,"startTime":66000},{"duration":5000,"content":"你永远不会被问到，很奇怪。","startOfParagraph":false,"startTime":69000},{"duration":2000,"content":"但是如果你被问及，","startOfParagraph":false,"startTime":74000},{"duration":2000,"content":"他们问:\"你从事什么行业?\"","startOfParagraph":false,"startTime":76000},{"duration":2000,"content":"你说你在教育部门工作","startOfParagraph":false,"startTime":78000},{"duration":4000,"content":"你会发现他们涨红了脸，那意思好像是","startOfParagraph":false,"startTime":80000},{"duration":6000,"content":"“我的天啊，” “为什么让我碰上？\n整整一周我才出来一次” (笑声)","startOfParagraph":false,"startTime":84000},{"duration":2000,"content":"但如果你要他们谈谈他们的受教育经历，","startOfParagraph":false,"startTime":90000},{"duration":2000,"content":"他们会把你“钉到墙上”。\n因为这些事情都涉及","startOfParagraph":false,"startTime":92000},{"duration":3000,"content":"个人的隐私,对吗?","startOfParagraph":false,"startTime":94000},{"duration":3000,"content":"比如宗教信仰,薪水等","startOfParagraph":false,"startTime":97000},{"duration":4000,"content":"我对教育特别感兴趣，\n我认为我们都是如此","startOfParagraph":false,"startTime":100000},{"duration":2000,"content":"我们对此有巨大的既得利益","startOfParagraph":false,"startTime":104000},{"duration":3000,"content":"部分因为教育旨在","startOfParagraph":false,"startTime":106000},{"duration":3000,"content":"将我们带入我们无法掌握的未来","startOfParagraph":false,"startTime":109000},{"duration":3000,"content":"大家想想，今年入学的小孩","startOfParagraph":false,"startTime":112000},{"duration":6000,"content":"2065将退休。没人知道会怎样--","startOfParagraph":false,"startTime":115000},{"duration":3000,"content":"虽然过去四天会议进程里\n都是关于这方面的专业讨论--","startOfParagraph":false,"startTime":121000},{"duration":2000,"content":"但我们还是无法预知这个世界","startOfParagraph":false,"startTime":124000},{"duration":2000,"content":"五年后的样子。\n这就是为何我们要让这些孩子","startOfParagraph":false,"startTime":126000},{"duration":3000,"content":"接受教育。我认为正是未来的不确定性","startOfParagraph":false,"startTime":128000},{"duration":2000,"content":"决定其非同寻常。","startOfParagraph":false,"startTime":131000},{"duration":2000,"content":"第三点就是","startOfParagraph":true,"startTime":133000},{"duration":5000,"content":"我们都认同一个观点--","startOfParagraph":false,"startTime":135000},{"duration":3000,"content":"这些孩子的特别之处正是","startOfParagraph":false,"startTime":140000},{"duration":2000,"content":"他们的创新能力。我觉得昨晚\nSirena 的表现令人惊奇，","startOfParagraph":false,"startTime":143000},{"duration":3000,"content":"对吗？","startOfParagraph":false,"startTime":145000},{"duration":5000,"content":"她很出色，但是我认为","startOfParagraph":false,"startTime":148000},{"duration":3000,"content":"她在孩提时代时没显得与众不同。","startOfParagraph":false,"startTime":153000},{"duration":3000,"content":"现在的教育提倡的是\n一个有奉献精神的老师","startOfParagraph":false,"startTime":156000},{"duration":2000,"content":"能发现一个天才学生。但我认为","startOfParagraph":false,"startTime":159000},{"duration":2000,"content":"所有孩子都是伟大的天才。","startOfParagraph":false,"startTime":161000},{"duration":2000,"content":"而我们却无情地扼杀了他们的才能。","startOfParagraph":false,"startTime":163000},{"duration":3000,"content":"所以我想谈谈教育和","startOfParagraph":false,"startTime":165000},{"duration":3000,"content":"创造力。我认为","startOfParagraph":false,"startTime":168000},{"duration":3000,"content":"创造力和文化知识在教育中占同样比重，","startOfParagraph":false,"startTime":171000},{"duration":4000,"content":"所以这两方面我们应同等对待。","startOfParagraph":false,"startTime":174000},{"duration":8000,"content":"（掌声）谢谢。而且，","startOfParagraph":false,"startTime":178000},{"duration":4000,"content":"非常感谢。（笑声）还剩15分钟。","startOfParagraph":false,"startTime":186000},{"duration":7000,"content":"我出生于--说错了（笑声）","startOfParagraph":false,"startTime":190000},{"duration":4000,"content":"最近我听到一个很不错的故事\n--我很愿意讲讲这个故事--","startOfParagraph":true,"startTime":197000},{"duration":4000,"content":"说的是一个小女孩正在上绘画课。\n小女孩只有六岁","startOfParagraph":false,"startTime":201000},{"duration":2000,"content":"她坐在教室的后排，正在画画，","startOfParagraph":false,"startTime":205000},{"duration":2000,"content":"而她的老师评价她几乎从不","startOfParagraph":false,"startTime":207000},{"duration":4000,"content":"注意听讲，但在绘画课上她却听得很认真。","startOfParagraph":false,"startTime":209000},{"duration":2000,"content":"老师饶有兴趣地走过去","startOfParagraph":false,"startTime":213000},{"duration":3000,"content":"问她：“你在画什么？”","startOfParagraph":false,"startTime":215000},{"duration":3000,"content":"她说：“我画的是上帝。”","startOfParagraph":false,"startTime":218000},{"duration":3000,"content":"老师说：“可是没人知道上帝长什么样。”","startOfParagraph":false,"startTime":221000},{"duration":7000,"content":"这时小女孩说：\n“他们马上就能知道上帝的样子了。”","startOfParagraph":false,"startTime":224000},{"duration":1000,"content":"（笑声）","startOfParagraph":false,"startTime":231000},{"duration":5000,"content":"我儿子四岁时在英国--","startOfParagraph":true,"startTime":232000},{"duration":3000,"content":"实际上他那会儿在哪都四岁（笑声）","startOfParagraph":false,"startTime":237000},{"duration":6000,"content":"严格地说他四岁那年在哪个国家记不清了，\n只记得他四岁那年","startOfParagraph":false,"startTime":240000},{"duration":2000,"content":"去演舞台剧《基督诞生》","startOfParagraph":false,"startTime":246000},{"duration":3000,"content":"你们记得那部剧的情节吗？\n应该记不得，情节太长。","startOfParagraph":false,"startTime":248000},{"duration":3000,"content":"故事太长。梅尔.吉布森演过那部剧的续集。","startOfParagraph":false,"startTime":251000},{"duration":5000,"content":"你们也许看过，叫《基督诞生II》。\n我儿子 James 在那部舞台剧里演 Joseph，","startOfParagraph":false,"startTime":254000},{"duration":3000,"content":"我们为此很兴奋。","startOfParagraph":false,"startTime":259000},{"duration":2000,"content":"我们以为那是个主要角色。","startOfParagraph":false,"startTime":262000},{"duration":2000,"content":"我们给观众们发了T恤：","startOfParagraph":false,"startTime":264000},{"duration":3000,"content":"上面印着\n“James Robinson 扮演 Joseph\" (笑声）","startOfParagraph":false,"startTime":266000},{"duration":2000,"content":"他的角色不一定有台词，剧情是","startOfParagraph":false,"startTime":269000},{"duration":3000,"content":"三个国王拿着礼物走进来","startOfParagraph":false,"startTime":271000},{"duration":2000,"content":"他们分别拿着黄金，乳香精油，没药精油。","startOfParagraph":false,"startTime":274000},{"duration":2000,"content":"演出开始了。我们坐在观众席上","startOfParagraph":false,"startTime":276000},{"duration":2000,"content":"我认为他们应该按顺序出场，","startOfParagraph":false,"startTime":278000},{"duration":2000,"content":"演出结束后我们对James说：","startOfParagraph":false,"startTime":280000},{"duration":2000,"content":"“你们刚才演的对吗？”\n他说：“对啊，怎么了，哪错了吗？”","startOfParagraph":false,"startTime":282000},{"duration":2000,"content":"其实他们把剧情改了。","startOfParagraph":false,"startTime":284000},{"duration":1000,"content":"他们是这么演的：三个小演员出场，","startOfParagraph":false,"startTime":286000},{"duration":2000,"content":"四岁的小家伙们头上戴着擦杯子用的毛巾，","startOfParagraph":false,"startTime":287000},{"duration":3000,"content":"他们放下手上拿的盒子","startOfParagraph":false,"startTime":289000},{"duration":2000,"content":"第一个孩子说：“我带来了黄金。”","startOfParagraph":false,"startTime":292000},{"duration":3000,"content":"第二个孩子说：“我带来了没药精油。”","startOfParagraph":false,"startTime":294000},{"duration":14000,"content":"第三个孩子说：\n“Frank带来了这个”（笑声）","startOfParagraph":false,"startTime":297000},{"duration":2000,"content":"以上例子的共同点就是孩子们愿意冒险。","startOfParagraph":true,"startTime":311000},{"duration":3000,"content":"对于未知的事物，他们愿意去尝试。","startOfParagraph":false,"startTime":313000},{"duration":3000,"content":"难道不是吗？\n即使尝试的结果是错误的，他们也不惧怕。","startOfParagraph":false,"startTime":316000},{"duration":5000,"content":"当然，我并不认为错误的尝试等同于创新。","startOfParagraph":false,"startTime":319000},{"duration":1000,"content":"但我们都知道","startOfParagraph":false,"startTime":324000},{"duration":3000,"content":"如果你不打算做错误的尝试","startOfParagraph":false,"startTime":325000},{"duration":3000,"content":"你永远不会创造出新东西。","startOfParagraph":false,"startTime":328000},{"duration":3000,"content":"如果你不想让孩子们做错误的尝试，\n等他们长大了，","startOfParagraph":false,"startTime":331000},{"duration":2000,"content":"多数孩子就会丧失创新的能力。","startOfParagraph":false,"startTime":334000},{"duration":3000,"content":"那就会使他们也变得惧怕错误的尝试。","startOfParagraph":false,"startTime":336000},{"duration":2000,"content":"这种情况也存在于公司经营方面。","startOfParagraph":false,"startTime":339000},{"duration":3000,"content":"我们不能容忍任何错误。\n这就使得现在的","startOfParagraph":false,"startTime":341000},{"duration":3000,"content":"教育体系成为","startOfParagraph":false,"startTime":344000},{"duration":3000,"content":"最不能容忍错误的领域。","startOfParagraph":false,"startTime":347000},{"duration":3000,"content":"这样做的后果就是\n我们的教育体制正在扼杀","startOfParagraph":false,"startTime":350000},{"duration":3000,"content":"孩子们的创造力。毕加索曾说过:","startOfParagraph":false,"startTime":353000},{"duration":3000,"content":"“孩子们是天生的艺术家”","startOfParagraph":false,"startTime":356000},{"duration":4000,"content":"问题是我们长大后\n能否继续保有艺术灵感。我坚信：","startOfParagraph":false,"startTime":359000},{"duration":2000,"content":"我们随着年龄的增长而丧失了创造力，","startOfParagraph":false,"startTime":363000},{"duration":3000,"content":"甚至可以说，是我们所受的教育\n让我们丧失了创造力。","startOfParagraph":false,"startTime":365000},{"duration":2000,"content":"为什么会这样？","startOfParagraph":false,"startTime":368000},{"duration":4000,"content":"五年前，我住在Stratford-on-Avon。","startOfParagraph":true,"startTime":370000},{"duration":2000,"content":"现在我已经搬到了洛杉矶。","startOfParagraph":false,"startTime":374000},{"duration":4000,"content":"可想而知，这是个多么合乎逻辑的移居。","startOfParagraph":false,"startTime":376000},{"duration":2000,"content":"（笑声）其实，","startOfParagraph":false,"startTime":380000},{"duration":2000,"content":"那时我们住在 Snitterfield","startOfParagraph":false,"startTime":382000},{"duration":2000,"content":"就在 Stratford 郊外，那里是","startOfParagraph":false,"startTime":384000},{"duration":5000,"content":"莎士比亚父亲的出生地。\n你有过灵感吗？我曾经有过。","startOfParagraph":false,"startTime":386000},{"duration":2000,"content":"你没把莎士比亚\n和他的父亲联想在一起，对吗？","startOfParagraph":false,"startTime":391000},{"duration":2000,"content":"因为你忽略了","startOfParagraph":false,"startTime":393000},{"duration":2000,"content":"莎士比亚也曾经是个孩子，对吗？","startOfParagraph":false,"startTime":395000},{"duration":3000,"content":"莎士比亚七岁时什么样？\n我从没想过--他七岁时","startOfParagraph":false,"startTime":397000},{"duration":2000,"content":"的某个特定场景。比如他在上","startOfParagraph":false,"startTime":400000},{"duration":9000,"content":"英语课，\n想想他在上英语课--多么不可思议","startOfParagraph":false,"startTime":402000},{"duration":14000,"content":"（笑声)“你要努力学习”\n你能想象他父亲边说边把他抱上床，","startOfParagraph":false,"startTime":411000},{"duration":3000,"content":"“现在该睡觉了”","startOfParagraph":false,"startTime":425000},{"duration":2000,"content":"他父亲又说：“放下笔，","startOfParagraph":false,"startTime":428000},{"duration":8000,"content":"别再写那些东西了，别人都看不懂。”","startOfParagraph":false,"startTime":430000},{"duration":5000,"content":"（笑声）","startOfParagraph":false,"startTime":438000},{"duration":3000,"content":"话说远了，刚才说到我们从\nStratford 搬到洛杉矶，","startOfParagraph":true,"startTime":443000},{"duration":4000,"content":"我想说的是，对于这次搬家，","startOfParagraph":false,"startTime":446000},{"duration":3000,"content":"我儿子并不愿意。","startOfParagraph":false,"startTime":450000},{"duration":3000,"content":"我有两个孩子。\n儿子现在21岁了，女儿16岁。","startOfParagraph":false,"startTime":453000},{"duration":2000,"content":"我儿子不愿搬到洛杉矶。\n虽然他喜欢这，","startOfParagraph":false,"startTime":456000},{"duration":5000,"content":"但在英国，他有个女友，\n是他的最爱，叫 Sarah。","startOfParagraph":false,"startTime":458000},{"duration":2000,"content":"他们认识只有一个月后就开始交往了。","startOfParagraph":false,"startTime":463000},{"duration":3000,"content":"我们要搬家时他们已交往了4年。","startOfParagraph":false,"startTime":465000},{"duration":4000,"content":"这对于16岁的年龄来说已经很长了。","startOfParagraph":false,"startTime":468000},{"duration":2000,"content":"我儿子上了飞机后很郁闷，","startOfParagraph":false,"startTime":472000},{"duration":2000,"content":"他说：“我再也找不到像\nSarah 那样的女孩了。”","startOfParagraph":false,"startTime":474000},{"duration":2000,"content":"但说实话，\n做为家长的我们为此很庆幸。","startOfParagraph":false,"startTime":476000},{"duration":12000,"content":"因为那个女孩是我们搬家的主要原因。","startOfParagraph":false,"startTime":478000},{"duration":3000,"content":"（笑声）","startOfParagraph":false,"startTime":490000},{"duration":3000,"content":"但搬到美国后，有些事使我印象深刻","startOfParagraph":true,"startTime":493000},{"duration":2000,"content":"如果你周游世界","startOfParagraph":false,"startTime":496000},{"duration":4000,"content":"你会发现每个国家的教育体系\n都存在相同的学科等级制度。","startOfParagraph":false,"startTime":498000},{"duration":2000,"content":"没有例外。不论哪个国家。","startOfParagraph":false,"startTime":502000},{"duration":2000,"content":"你认为也许会有例外，但没有。","startOfParagraph":false,"startTime":504000},{"duration":3000,"content":"排在最前面的学科是数学和语言，","startOfParagraph":false,"startTime":506000},{"duration":2000,"content":"接下去是人文学科，艺术排在最后。","startOfParagraph":false,"startTime":509000},{"duration":2000,"content":"世界上所有国家都是如此。","startOfParagraph":false,"startTime":511000},{"duration":3000,"content":"而且相同的还有","startOfParagraph":false,"startTime":513000},{"duration":2000,"content":"就是在艺术学科范围内也有等级制。","startOfParagraph":false,"startTime":516000},{"duration":2000,"content":"通常学校把美术课和音乐课看的较重要","startOfParagraph":false,"startTime":518000},{"duration":3000,"content":"然后是戏剧课和舞蹈课。\n没有哪个国家的教育体系","startOfParagraph":false,"startTime":520000},{"duration":2000,"content":"天天安排舞蹈课","startOfParagraph":false,"startTime":523000},{"duration":3000,"content":"但却每天都安排数学课。为什么？","startOfParagraph":false,"startTime":525000},{"duration":2000,"content":"为什么不是每天安排舞蹈课呢？\n我认为舞蹈课很重要。","startOfParagraph":false,"startTime":528000},{"duration":3000,"content":"我认为舞蹈课和数学课同样重要。","startOfParagraph":false,"startTime":530000},{"duration":3000,"content":"如果有允许，孩子们会不停地跳舞，\n我们也一样。","startOfParagraph":false,"startTime":533000},{"duration":3000,"content":"我们都有体会，对吗？","startOfParagraph":false,"startTime":536000},{"duration":4000,"content":"（笑声）事实上，","startOfParagraph":false,"startTime":539000},{"duration":2000,"content":"随着孩子年龄增长，我们开始教导他们","startOfParagraph":false,"startTime":543000},{"duration":3000,"content":"别的东西，（以前是教他们走和跑），\n而随着他们长大，我们更关注的是他们的头脑。","startOfParagraph":false,"startTime":545000},{"duration":2000,"content":"而且略微偏重大脑的一侧。","startOfParagraph":false,"startTime":548000},{"duration":4000,"content":"如果你以一个外国人的身份来参观我们的教育体系，","startOfParagraph":true,"startTime":550000},{"duration":3000,"content":"带着这样的问题：“公办教育的目的是什么？”","startOfParagraph":false,"startTime":554000},{"duration":2000,"content":"那么当你看到我们的教育体系产业化的发展，\n我相信，你就会明白","startOfParagraph":false,"startTime":557000},{"duration":2000,"content":"是谁在真正从中受益，","startOfParagraph":false,"startTime":559000},{"duration":2000,"content":"是谁被教导着该做什么不该做什么，","startOfParagraph":false,"startTime":561000},{"duration":3000,"content":"是谁得了满分，谁是第一名--","startOfParagraph":false,"startTime":563000},{"duration":3000,"content":"关于公办教育的目的，\n我想你会得出这样的结论","startOfParagraph":false,"startTime":566000},{"duration":1000,"content":"世界上所有的公办教育","startOfParagraph":false,"startTime":569000},{"duration":4000,"content":"都以培养大学教授为目的。难道不是吗？","startOfParagraph":false,"startTime":570000},{"duration":2000,"content":"因为大学教授是象牙塔尖上的人。","startOfParagraph":false,"startTime":574000},{"duration":3000,"content":"我也曾是一名大学教授，\n也是塔尖上的人。（笑声）","startOfParagraph":false,"startTime":577000},{"duration":4000,"content":"我倾慕大学教授的学识，但","startOfParagraph":false,"startTime":580000},{"duration":4000,"content":"我们不应该用这样一个头衔作为\n衡量一个人成功与否的分水岭。","startOfParagraph":false,"startTime":584000},{"duration":2000,"content":"其实大学教授只是360行中的一行，","startOfParagraph":false,"startTime":588000},{"duration":2000,"content":"只不过他们比较好求知，","startOfParagraph":false,"startTime":590000},{"duration":2000,"content":"我这样说不是因为对他们的倾慕。","startOfParagraph":false,"startTime":592000},{"duration":3000,"content":"在我看来，大学教授有个特点--","startOfParagraph":false,"startTime":594000},{"duration":3000,"content":"虽然不是共性，但很典型--\n他们只用脑子生活。","startOfParagraph":false,"startTime":597000},{"duration":2000,"content":"而且偏重于大脑的一侧。","startOfParagraph":false,"startTime":600000},{"duration":4000,"content":"用书面语来说就是--他们脑体分离。","startOfParagraph":false,"startTime":602000},{"duration":2000,"content":"他们只是把身体当作","startOfParagraph":false,"startTime":606000},{"duration":9000,"content":"大脑的载体而已，难道不是吗？","startOfParagraph":false,"startTime":608000},{"duration":7000,"content":"（笑声)这个载体可以载着大脑去开会。","startOfParagraph":false,"startTime":617000},{"duration":3000,"content":"如果你想亲身体验","startOfParagraph":false,"startTime":624000},{"duration":3000,"content":"你就去参加一次会议","startOfParagraph":false,"startTime":627000},{"duration":2000,"content":"--学术研讨会，","startOfParagraph":false,"startTime":630000},{"duration":3000,"content":"然后在会议结束后再去迪厅蹦迪。","startOfParagraph":false,"startTime":632000},{"duration":4000,"content":"（笑声）在那你会看到，成年男女","startOfParagraph":false,"startTime":635000},{"duration":4000,"content":"在不和乐拍地疯狂摇摆。","startOfParagraph":false,"startTime":639000},{"duration":4000,"content":"期待夜晚的结束好回家\n写篇关于蹦迪的论文。","startOfParagraph":false,"startTime":643000},{"duration":6000,"content":"注重培养学术能力的观点根植于\n我们的教育体系之中。","startOfParagraph":true,"startTime":647000},{"duration":3000,"content":"形成这种状况还有个原因--","startOfParagraph":false,"startTime":653000},{"duration":2000,"content":"所有国家的教育体系在最初建立时","startOfParagraph":false,"startTime":656000},{"duration":2000,"content":"也就是在19世纪之前--\n那时教育还不是公共事业。","startOfParagraph":false,"startTime":658000},{"duration":3000,"content":"那时建立教育体系","startOfParagraph":false,"startTime":660000},{"duration":1000,"content":"是为了满足工业化发展的需要。","startOfParagraph":false,"startTime":663000},{"duration":3000,"content":"所以有两点基本的等级原则。","startOfParagraph":false,"startTime":664000},{"duration":4000,"content":"第一点，对工作最实用的科目","startOfParagraph":false,"startTime":667000},{"duration":2000,"content":"是最重要的科目。\n这样就能轻易地避开","startOfParagraph":false,"startTime":671000},{"duration":2000,"content":"孩子们喜欢的科目，\n从小就不让他们碰触。","startOfParagraph":false,"startTime":673000},{"duration":2000,"content":"理由就是","startOfParagraph":false,"startTime":675000},{"duration":3000,"content":"不这样学就找不到工作。对吗？","startOfParagraph":false,"startTime":677000},{"duration":2000,"content":"别玩音乐了，你成不了音乐家；","startOfParagraph":false,"startTime":680000},{"duration":2000,"content":"别画画了，你成不了艺术家。","startOfParagraph":false,"startTime":682000},{"duration":4000,"content":"这些温和的忠告--\n筑成现在的大错。全世界","startOfParagraph":false,"startTime":685000},{"duration":1000,"content":"都被卷入了工业革命的热潮。","startOfParagraph":false,"startTime":689000},{"duration":3000,"content":"第二点，学术能力已经成为","startOfParagraph":false,"startTime":690000},{"duration":1000,"content":"衡量好学生的主要标准","startOfParagraph":false,"startTime":693000},{"duration":3000,"content":"这种标准是那些大学自己制定的。","startOfParagraph":false,"startTime":694000},{"duration":2000,"content":"只要你思考一下就会发现整个教育体系","startOfParagraph":false,"startTime":697000},{"duration":2000,"content":"不论哪个国家的公共教育\n都是一种按部就班的程序","startOfParagraph":false,"startTime":699000},{"duration":2000,"content":"最终目标是为了考入大学。","startOfParagraph":false,"startTime":701000},{"duration":3000,"content":"造成的后果就是许多很有天才的","startOfParagraph":false,"startTime":703000},{"duration":2000,"content":"有创造力的学生被钝化了。","startOfParagraph":false,"startTime":706000},{"duration":2000,"content":"因为这些学生发现他们的专长在学校","startOfParagraph":false,"startTime":708000},{"duration":4000,"content":"并不受重视甚至还受到蔑视。","startOfParagraph":false,"startTime":710000},{"duration":2000,"content":"我认为我们不能再这样扼杀孩子们的天才了。","startOfParagraph":false,"startTime":714000},{"duration":2000,"content":"根据联合国教科文组织的统计，今后30年","startOfParagraph":true,"startTime":716000},{"duration":3000,"content":"全世界毕业的学生将超过","startOfParagraph":false,"startTime":718000},{"duration":2000,"content":"过去的总和。","startOfParagraph":false,"startTime":721000},{"duration":2000,"content":"这就是人口增长造成的，\n人口增长关系到","startOfParagraph":false,"startTime":723000},{"duration":2000,"content":"我们谈论的许多话题--","startOfParagraph":false,"startTime":725000},{"duration":3000,"content":"包括技术和技术变革\n对生产力的影响、人口统计学","startOfParagraph":false,"startTime":727000},{"duration":2000,"content":"及人口爆炸。","startOfParagraph":false,"startTime":730000},{"duration":3000,"content":"很快，文凭就不再有含金量了。是这样吧？","startOfParagraph":false,"startTime":732000},{"duration":4000,"content":"我上学那会儿，有文凭就有工作。","startOfParagraph":false,"startTime":735000},{"duration":3000,"content":"那时候如果你没工作，那是因为你不想找。","startOfParagraph":false,"startTime":739000},{"duration":3000,"content":"说实话，我那时候就是这样。（笑声）","startOfParagraph":false,"startTime":742000},{"duration":5000,"content":"但现在的状况是，孩子们有文凭却经常","startOfParagraph":false,"startTime":745000},{"duration":1000,"content":"呆在家里打电脑游戏，","startOfParagraph":false,"startTime":750000},{"duration":3000,"content":"因为以前只要学士学位的工作岗位\n现在需要硕士学位，","startOfParagraph":false,"startTime":751000},{"duration":3000,"content":"现在还没毕业的孩子将来\n就得有个博士学位才好找工作。","startOfParagraph":false,"startTime":754000},{"duration":2000,"content":"这就是学术学位的通货膨胀。","startOfParagraph":false,"startTime":757000},{"duration":2000,"content":"这是整个教育体系","startOfParagraph":false,"startTime":759000},{"duration":2000,"content":"坍塌的前兆。我们必须从根本上反思","startOfParagraph":false,"startTime":761000},{"duration":1000,"content":"我们评价好学生的标准。","startOfParagraph":false,"startTime":763000},{"duration":2000,"content":"培养人才有三个原则","startOfParagraph":true,"startTime":764000},{"duration":3000,"content":"第一，多样化。\n我们认知世界的角度不同","startOfParagraph":false,"startTime":766000},{"duration":2000,"content":"有的从视觉角度，","startOfParagraph":false,"startTime":769000},{"duration":3000,"content":"有的从听觉角度，有的从美学角度","startOfParagraph":false,"startTime":771000},{"duration":3000,"content":"有的从抽象的角度，\n有的从动态的角度。","startOfParagraph":false,"startTime":774000},{"duration":2000,"content":"第二，好学生应该是充满活力的。","startOfParagraph":false,"startTime":777000},{"duration":3000,"content":"如果观察一下人类大脑的内部组织，就像我们","startOfParagraph":false,"startTime":779000},{"duration":3000,"content":"昨天所看到的演讲中演示的，","startOfParagraph":false,"startTime":782000},{"duration":2000,"content":"大脑发育具有关联性。","startOfParagraph":false,"startTime":785000},{"duration":3000,"content":"大脑不应被分成几部分。","startOfParagraph":false,"startTime":787000},{"duration":3000,"content":"其实我认为应该创造性地\n把大脑看作一整套工序--","startOfParagraph":false,"startTime":790000},{"duration":2000,"content":"生产有价值的原创想法的工序--","startOfParagraph":false,"startTime":793000},{"duration":3000,"content":"这种原创想法往往来自互动的思考方式","startOfParagraph":false,"startTime":795000},{"duration":3000,"content":"而不是呆板的常规模式。","startOfParagraph":false,"startTime":798000},{"duration":2000,"content":"大脑本来就是","startOfParagraph":true,"startTime":801000},{"duration":3000,"content":"由神经来连接左脑和右脑","startOfParagraph":false,"startTime":803000},{"duration":2000,"content":"这个连接部分叫胼胝体（医学名词）。\n女性大脑中的这个部分比男性的要厚。","startOfParagraph":false,"startTime":806000},{"duration":2000,"content":"昨天听了Helen的演讲受到启发，我认为","startOfParagraph":false,"startTime":808000},{"duration":4000,"content":"脑部特征可能使女性更善于\n应对头绪纷乱的事情。","startOfParagraph":false,"startTime":810000},{"duration":2000,"content":"对吗？","startOfParagraph":false,"startTime":814000},{"duration":3000,"content":"虽然关于这方面的研究有很多，\n但我对于这方面的了解 其实来源于我的亲身体验。","startOfParagraph":false,"startTime":816000},{"duration":2000,"content":"我妻子在家做饭时--","startOfParagraph":false,"startTime":819000},{"duration":4000,"content":"感谢上帝，她不常做饭，（笑声）","startOfParagraph":false,"startTime":821000},{"duration":3000,"content":"虽然她不擅厨艺但很擅长其他一些事--","startOfParagraph":false,"startTime":825000},{"duration":2000,"content":"不过她做饭时总是","startOfParagraph":false,"startTime":828000},{"duration":2000,"content":"打打电话，","startOfParagraph":false,"startTime":830000},{"duration":3000,"content":"和孩子们说说话，给天棚刷刷漆，","startOfParagraph":false,"startTime":832000},{"duration":3000,"content":"还在旁边做开胸手术。","startOfParagraph":false,"startTime":835000},{"duration":3000,"content":"而我做饭时就会关上厨房门，\n不让孩子们进来打扰，","startOfParagraph":false,"startTime":838000},{"duration":3000,"content":"不打电话，这时如果我妻子进来我会很生气。","startOfParagraph":false,"startTime":841000},{"duration":13000,"content":"我会这样对我妻子说：\n“Terry，我在煎鸡蛋，请你别打扰。”（笑声）","startOfParagraph":false,"startTime":844000},{"duration":2000,"content":"大家都知道那句有哲理的话--","startOfParagraph":false,"startTime":857000},{"duration":3000,"content":"如果森林里有棵树倒了可没人听到，","startOfParagraph":false,"startTime":859000},{"duration":3000,"content":"那是否意味着没发生过？记得这句话吗？","startOfParagraph":false,"startTime":862000},{"duration":3000,"content":"最近我看到一件很棒的T恤，\n上面印着：“如果一个男人说出他的心声","startOfParagraph":false,"startTime":865000},{"duration":3000,"content":"却是在森林里说的，而且没被女人听到，","startOfParagraph":false,"startTime":868000},{"duration":9000,"content":"那应该不算犯错吧？”（笑声）","startOfParagraph":false,"startTime":871000},{"duration":2000,"content":"培养好学生的第三个原则就是--","startOfParagraph":true,"startTime":880000},{"duration":2000,"content":"个性化。我目前在写本书--","startOfParagraph":false,"startTime":883000},{"duration":2000,"content":"书名叫《顿悟》，素材来自一些","startOfParagraph":false,"startTime":885000},{"duration":2000,"content":"访谈，访谈内容是关于怎样发现","startOfParagraph":false,"startTime":887000},{"duration":2000,"content":"自身的才能。对于这点我很感兴趣。","startOfParagraph":false,"startTime":889000},{"duration":3000,"content":"激发我写这本书的原因是一次对话","startOfParagraph":false,"startTime":891000},{"duration":2000,"content":"我采访了一位很优秀的女士，也许很多人","startOfParagraph":false,"startTime":894000},{"duration":2000,"content":"没听说过这个人，她叫Gillian Lynne,","startOfParagraph":false,"startTime":896000},{"duration":2000,"content":"你们知道这个人吗？应该有人知道吧。\n她是一个舞蹈编剧","startOfParagraph":false,"startTime":898000},{"duration":2000,"content":"所有人都知道她的作品。","startOfParagraph":false,"startTime":900000},{"duration":2000,"content":"她编舞的作品有《猫》、《歌剧魅影》。","startOfParagraph":false,"startTime":902000},{"duration":4000,"content":"她很有才华。我在英国看过\n由皇家芭蕾舞团演出的她的作品。","startOfParagraph":false,"startTime":904000},{"duration":2000,"content":"你们也看过她的作品。","startOfParagraph":false,"startTime":908000},{"duration":2000,"content":"有一次，我和Gillian 吃午饭，我问她：","startOfParagraph":false,"startTime":910000},{"duration":2000,"content":"“Gillian,你是怎样成为舞蹈家的？她回答说：","startOfParagraph":false,"startTime":912000},{"duration":2000,"content":"说起来很有意思，她上学的时候，","startOfParagraph":false,"startTime":914000},{"duration":3000,"content":"觉得自己完全没有希望。\n她上学那会儿是1930年代，","startOfParagraph":false,"startTime":916000},{"duration":2000,"content":"老师给她家长写信说：“我们认为","startOfParagraph":false,"startTime":919000},{"duration":2000,"content":"Gillian患有学习障碍症。”她无法集中注意力，","startOfParagraph":false,"startTime":921000},{"duration":2000,"content":"她老是坐不安生。\n用现在的话讲，那意思就是","startOfParagraph":false,"startTime":923000},{"duration":4000,"content":"她有多动症。你们也这么想吧？\n但那时候是1930年代，","startOfParagraph":false,"startTime":925000},{"duration":3000,"content":"“多动症”这个词还没出现。","startOfParagraph":false,"startTime":929000},{"duration":3000,"content":"那个老师用词不当。（笑声）","startOfParagraph":false,"startTime":932000},{"duration":4000,"content":"那时候人们还不知道用“多动症”这个词。","startOfParagraph":false,"startTime":935000},{"duration":4000,"content":"于是，Gillian去看病。","startOfParagraph":true,"startTime":939000},{"duration":3000,"content":"她妈妈带她去的，","startOfParagraph":false,"startTime":943000},{"duration":3000,"content":"医生让她坐在椅子上，","startOfParagraph":false,"startTime":946000},{"duration":2000,"content":"她把手压在腿下，这样过了20分钟","startOfParagraph":false,"startTime":949000},{"duration":2000,"content":"她妈妈一直在向医生讲述","startOfParagraph":false,"startTime":951000},{"duration":4000,"content":"Gillian在学校的表现：","startOfParagraph":false,"startTime":953000},{"duration":2000,"content":"她在学校不安生，","startOfParagraph":false,"startTime":957000},{"duration":2000,"content":"她总是晚交作业，等等，","startOfParagraph":false,"startTime":959000},{"duration":3000,"content":"其实不过是个才8岁的孩子--最后，\n医生走过去坐到","startOfParagraph":false,"startTime":961000},{"duration":2000,"content":"Gillian的旁边对她说：“Gillian,","startOfParagraph":false,"startTime":964000},{"duration":2000,"content":"你妈妈跟我说了很多","startOfParagraph":false,"startTime":966000},{"duration":2000,"content":"现在我想和你妈妈单独谈谈。”","startOfParagraph":false,"startTime":968000},{"duration":3000,"content":"“你在这儿等一下，我们马上谈完。”","startOfParagraph":false,"startTime":970000},{"duration":2000,"content":"医生和她妈妈出去了。","startOfParagraph":false,"startTime":973000},{"duration":2000,"content":"但医生在出去时把收音机打开了","startOfParagraph":false,"startTime":975000},{"duration":2000,"content":"收音机在医生办公桌上。在他们","startOfParagraph":false,"startTime":977000},{"duration":2000,"content":"走出房间后，医生对她妈妈说:","startOfParagraph":false,"startTime":979000},{"duration":3000,"content":"“我们就站在这儿观察一下她。\n”他们离开房间后，","startOfParagraph":false,"startTime":981000},{"duration":4000,"content":"Gillian站起来，随着音乐跳起舞来。","startOfParagraph":false,"startTime":984000},{"duration":2000,"content":"她妈妈和医生在门外看了几分钟","startOfParagraph":false,"startTime":988000},{"duration":3000,"content":"医生对她妈妈说：","startOfParagraph":false,"startTime":990000},{"duration":4000,"content":"Lynne太太，Gillian没病，\n她是个舞蹈天才。","startOfParagraph":false,"startTime":993000},{"duration":2000,"content":"让她去上舞蹈学校吧。”","startOfParagraph":false,"startTime":997000},{"duration":2000,"content":"话说到这，我问Gillian：“后来怎么样了？”","startOfParagraph":true,"startTime":999000},{"duration":3000,"content":"她回答道：“我妈妈送我去了舞蹈学校。\n我无法形容那里有多棒。","startOfParagraph":false,"startTime":1001000},{"duration":2000,"content":"那里有很多","startOfParagraph":false,"startTime":1004000},{"duration":3000,"content":"像我这样的人--坐不住的人。","startOfParagraph":false,"startTime":1006000},{"duration":3000,"content":"我们必须在动态中才能思考。”","startOfParagraph":false,"startTime":1009000},{"duration":2000,"content":"他们跳芭蕾，跳踢踏舞，跳爵士舞，","startOfParagraph":false,"startTime":1012000},{"duration":2000,"content":"跳现代舞。","startOfParagraph":false,"startTime":1014000},{"duration":3000,"content":"后来她考入皇家芭蕾舞学校，","startOfParagraph":false,"startTime":1016000},{"duration":2000,"content":"成为芭蕾舞女主演，事业发展很成功","startOfParagraph":false,"startTime":1019000},{"duration":2000,"content":"从那毕业后","startOfParagraph":false,"startTime":1021000},{"duration":2000,"content":"从皇家芭蕾舞学校毕业后","startOfParagraph":false,"startTime":1023000},{"duration":3000,"content":"她成立了自己的公司\n--Gillian Lynne 舞蹈公司","startOfParagraph":false,"startTime":1025000},{"duration":3000,"content":"遇到了Andrew Lloyd Weber\n（注：歌舞剧《猫》的编曲者）。她负责","startOfParagraph":false,"startTime":1028000},{"duration":2000,"content":"担任过一些极其成功的音乐剧的编舞","startOfParagraph":false,"startTime":1031000},{"duration":5000,"content":"她给数以万计的观众带来了艺术享受，","startOfParagraph":false,"startTime":1033000},{"duration":3000,"content":"她也是个亿万富翁。可是，有人","startOfParagraph":false,"startTime":1038000},{"duration":4000,"content":"也许曾认为她有多动症命令她","startOfParagraph":false,"startTime":1041000},{"duration":2000,"content":"“冷静。”","startOfParagraph":false,"startTime":1045000},{"duration":3000,"content":"现在，我想说的是--（掌声）","startOfParagraph":true,"startTime":1047000},{"duration":2000,"content":"AL Gore（注：美国前副总统） \n曾在这里做过一次演讲","startOfParagraph":false,"startTime":1050000},{"duration":3000,"content":"内容是关于生态学以及Rachel Carson\n引发的那次环境保护运动。","startOfParagraph":false,"startTime":1052000},{"duration":4000,"content":"我相信对于未来，我们的唯一出路","startOfParagraph":false,"startTime":1055000},{"duration":3000,"content":"是贯彻一种新的人性化生态的思想，","startOfParagraph":false,"startTime":1059000},{"duration":4000,"content":"也就是说我们应重新定义","startOfParagraph":false,"startTime":1062000},{"duration":2000,"content":"人类能力的多样化。","startOfParagraph":false,"startTime":1066000},{"duration":4000,"content":"我们的教育体系培养我们的方式","startOfParagraph":false,"startTime":1068000},{"duration":2000,"content":"正如我们开采地球的方式--\n以功利为目的。","startOfParagraph":false,"startTime":1072000},{"duration":3000,"content":"但这种方式对于未来将不再适用。","startOfParagraph":false,"startTime":1074000},{"duration":3000,"content":"我们必须重新思考那些最基本的准则","startOfParagraph":false,"startTime":1077000},{"duration":2000,"content":"也就是我们教育孩子的准则。","startOfParagraph":false,"startTime":1080000},{"duration":4000,"content":"Jonas Salk曾说过：“如果所有的昆虫","startOfParagraph":false,"startTime":1082000},{"duration":3000,"content":"都从地球上消失的话，","startOfParagraph":false,"startTime":1086000},{"duration":3000,"content":"那么50年之内，所有生命也将从地球上消失。","startOfParagraph":false,"startTime":1089000},{"duration":3000,"content":"而如果人类从地球上消失的话，","startOfParagraph":false,"startTime":1092000},{"duration":4000,"content":"那么50年之内，其他物种会活得更好。”","startOfParagraph":false,"startTime":1095000},{"duration":2000,"content":"他说的很对。","startOfParagraph":false,"startTime":1099000},{"duration":3000,"content":"TED倡导的是人类的创造性思维。","startOfParagraph":true,"startTime":1101000},{"duration":4000,"content":"现在，我们必须运用这种思维方式小心地","startOfParagraph":false,"startTime":1104000},{"duration":3000,"content":"避开那些按部就班的规则","startOfParagraph":false,"startTime":1108000},{"duration":3000,"content":"达到这个目的唯一的方法","startOfParagraph":false,"startTime":1111000},{"duration":3000,"content":"就是运用创造力","startOfParagraph":false,"startTime":1115000},{"duration":2000,"content":"最大限度地发挥创造力，而且","startOfParagraph":false,"startTime":1118000},{"duration":3000,"content":"用孩子们喜欢的方式培养他们。\n我们的任务","startOfParagraph":false,"startTime":1120000},{"duration":3000,"content":"是全方位地培养孩子，\n这样他们才能面对未来的社会。","startOfParagraph":false,"startTime":1123000},{"duration":3000,"content":"顺便说句--我们可能活不到未来那天","startOfParagraph":false,"startTime":1126000},{"duration":3000,"content":"但孩子们会。而我们要做的就是帮助","startOfParagraph":false,"startTime":1129000},{"duration":2000,"content":"他们能在未来有所作为。谢谢大家。","startOfParagraph":false,"startTime":1132000}]
};
